CREATE TABLE `funcionario` (
  `ID_AREA` int NOT NULL,
  `ID_DEPARTAMENTO` int NOT NULL,
  `ID_GESTOR` int NOT NULL,
  `ID_FUNCIONARIO` int NOT NULL AUTO_INCREMENT,
  `NOME` varchar(150) NOT NULL,
  `DATA_ADMISSAO` date NOT NULL,
  `DESCRICAO_CARGO` varchar(100) NOT NULL,
  `CATEGORIA_CARGO` enum('Assistente','Analista','Supervisor','Coordenador','Gerente','Diretor') NOT NULL,
  `NIVEL_CARGO` enum('Júnior','Pleno','Sênior') NOT NULL,
  `DATA_NASCIMENTO` date NOT NULL,
  `RUA` varchar(150) NOT NULL,
  `CEP` varchar(20) NOT NULL,
  `NUMERO` int NOT NULL,
  `ESTADO` varchar(2) NOT NULL,
  `CIDADE` varchar(100) NOT NULL,
  `BAIRRO` varchar(100) NOT NULL,
  `COMPLEMENTO` varchar(100) DEFAULT NULL,
  `GENERO` enum('F','M','Não Binário','Outro','Prefere não informar') NOT NULL,
  `CPF` varchar(20) NOT NULL,
  `RG` varchar(20) NOT NULL,
  `EMAIL` varchar(150) NOT NULL,
  `TELEFONE` varchar(30) NOT NULL,
  `ESCOLARIDADE` enum('Ensino Médio — Concluído','Ensino Superior — Cursando','Ensino Superior — Concluído','Pós-graduação — Cursando','Pós-graduação — Concluída','Outra Opção') NOT NULL,
  `REGIME_CONTRATACAO` enum('CLT','PJ') NOT NULL,
  `STATUS` enum('Ativo','Inativo') NOT NULL,
  `ETNIA` enum('Branca','Preta','Parda','Amarela','Indígena','Prefere não informar') NOT NULL,
  `PCD` enum('Sim','Não') NOT NULL,
  `ESTADO_CIVIL` enum('Solteiro(a)','Casado(a)','União Estável','Divorciado(a)','Viúvo(a)','Prefere não informar') NOT NULL,
  `MODALIDADE` enum('Presencial','Home Office') NOT NULL,
  `SALARIO` decimal(10,2) NOT NULL,
  `ID_PACOTE_BENEFICIO` int NOT NULL,
  PRIMARY KEY (`ID_FUNCIONARIO`),
  KEY `FK_FUNC_AREA` (`ID_AREA`),
  KEY `FK_FUNC_DEPARTAMENTO` (`ID_DEPARTAMENTO`),
  KEY `FK_FUNC_GESTOR` (`ID_GESTOR`),
  KEY `FK_FUNC_BENEFICIO` (`ID_PACOTE_BENEFICIO`),
  CONSTRAINT `FK_FUNC_AREA` FOREIGN KEY (`ID_AREA`) REFERENCES `cadastro_geral`.`area` (`ID_Area`),
  CONSTRAINT `FK_FUNC_BENEFICIO` FOREIGN KEY (`ID_PACOTE_BENEFICIO`) REFERENCES `pacote_beneficio` (`ID_Pacote_Beneficio`),
  CONSTRAINT `FK_FUNC_DEPARTAMENTO` FOREIGN KEY (`ID_DEPARTAMENTO`) REFERENCES `cadastro_geral`.`departamento` (`ID_Departamento`),
  CONSTRAINT `FK_FUNC_GESTOR` FOREIGN KEY (`ID_GESTOR`) REFERENCES `cadastro_geral`.`gestor` (`ID_Gestor`)
) ENGINE=InnoDB AUTO_INCREMENT=777 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;
